import {escapeHtml as esc,safeHttpUrl} from './checks.js';
const $=s=>document.querySelector(s);
const dialog=$('#info-dialog');
const labels={size:'Page size',bleed:'Bleed',resolution:'Image quality',margin:'Text margins',dates:'Dates & details',qr:'QR codes',ocr:'Text recognition',spelling:'Spelling',reference:'Your reference details',fonts:'Font embedding',colour:'Colour spaces'};
const statusLabels={warning:'Needs attention',manual:'Human check',pass:'Checked',info:'Note'};
let report=null,currentFile=null,currentBytes=null,controller=null,pageIndex=0,filter='all',category='all',selectedFinding=null,confirmations=new Set(),reviewed=new Set(),notes='',busy=false;
const checklistFor=type=>[
 ['copy','Names, spelling and contact details','I compared the artwork with the original details, including phone numbers and email addresses.'],
 ['dates',type==='invitation'?'Date, time, venue and RSVP details':'Dates, prices and factual details','I checked the intended information, not just whether the text looks correct.'],
 ['layout','Size, margins and page order','I checked the finished dimensions, every page and the areas flagged in the report.'],
 ['qr','QR codes and link destinations','I opened each relevant destination and checked the content. If there are no codes or links, this does not apply.'],
 ['production','Printer specifications and a physical proof','I confirmed bleed, colour, fonts, stock and finishing with the printer, and reviewed a physical proof.'],
 ...(type==='label'?[['label','Label information and barcode','I confirmed the product details, required label information and barcode with the responsible person.']]:[])
];
function showInfo(kind){$('#dialog-content').innerHTML=kind==='privacy'?`<h2>Your file stays on your device.</h2><p>The PDF is processed in this browser. Your artwork and report are not uploaded, saved to an account or sent to an AI service. Refreshing or closing the page clears the current check.</p><p>Downloaded reports contain extracted text and findings. Share them only with people who should see your artwork details.</p><p>QR destinations open only when you choose to visit them. They are external websites and have their own privacy policies.</p><h3>About this beta</h3><p>The automated check is free to try. The software runs checks and generates reports automatically; there is no human reviewer service. The proposed print shop pilot is ₹499 for 20 PDF checks, following three free checks for participating shops. Payments and usage limits are not connected yet. Checklist confirmations record your own review.</p>`:`<h2>What the software checks automatically</h2><dl class="check-definitions"><dt>Page size & bleed</dt><dd>Compares PDF trim dimensions with your selected size and checks declared bleed boxes. Does not verify ink coverage in the bleed area.</dd><dt>Images & text margins</dt><dd>Estimates effective raster-image DPI and selectable-text bounds. English OCR attempts to read image and outlined text. Low-confidence readings and approximate bounds still need visual review. Cropping and complex artwork can produce false positives.</dd><dt>Dates</dt><dd>Checks English day–month–year and month–day–year dates, including weekday mismatches and impossible dates. Numeric dates and multiple dates are flagged for confirmation. OCR readings are labelled separately and need confirmation.</dd><dt>Spelling & correct details</dt><dd>British English dictionary suggestions flag unrecognised words without changing them. Compare supplied names, venue, date and exact phrases against selectable text and OCR. A match establishes presence, not truth or correct placement.</dd><dt>Fonts & colours</dt><dd>Inspect referenced font resources for embedded data and identify declared or directly used colour spaces. Flag RGB if you select a CMYK requirement and report output-profile presence. These checks do not validate font integrity, ICC profile accuracy or physical colour reproduction.</dd><dt>QR codes</dt><dd>Attempts to decode up to six QR codes per page from a bounded preview. Small or stylised codes may be missed. We do not automatically visit or verify destinations.</dd></dl><h3>Your printer makes the final call.</h3><p>This is not a full PDF/X preflight. Font integrity, colour accuracy, ink limits, overprint, transparency, barcodes and production suitability need your printer’s review and a physical proof.</p>`;dialog.showModal();}
$('#about-button').onclick=()=>showInfo('checks');$('#privacy-button').onclick=()=>showInfo('privacy');$('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
$('#size-preset').onchange=e=>$('#custom-size').hidden=e.target.value!=='custom';
function referenceLines(id,max){const lines=$(id).value.split('\n').map(v=>v.trim()).filter(Boolean);if(lines.length>max||lines.some(v=>v.length>150))throw new Error(`Use at most ${max} lines, with no more than 150 characters per line, in the correct-details fields.`);return lines;}
function getSettings(){const preset=$('#size-preset').value;let size={a4:[210,297],a5:[148,210],'5x7':[127,177.8]}[preset]||null;if(preset==='custom'){size=[Number($('#custom-width').value),Number($('#custom-height').value)];if(size.some(v=>!Number.isFinite(v)||v<10||v>2000))throw new Error('Enter a custom width and height between 10 and 2,000 mm.');}return {type:$('#project-type').value,size,dpi:Number($('#dpi').value),margin:Number($('#safe-margin').value),bleed:$('#bleed-needed').checked,ocr:$('#ocr-enabled').checked,spelling:$('#spelling-enabled').checked,colourTarget:$('#colour-target').value,allowedWords:$('#allowed-words').value.split('\n').map(v=>v.trim()).filter(Boolean).slice(0,30),references:{names:referenceLines('#reference-names',8),venue:$('#reference-venue').value.trim(),date:$('#reference-date').value,details:referenceLines('#reference-details',8)}};}
function notify(message){$('#notice').textContent=message;$('#notice').hidden=!message;}
function setBusy(value){busy=value;$('#setup').hidden=value||!!report;$('#processing').hidden=!value;$('#sample-button').disabled=value;$('#file-input').disabled=value;}
async function startCheck(file,bytes){if(busy)return;notify('');let settings;try{settings=file.demo?{type:'invitation',size:null,dpi:300,margin:3,bleed:true,ocr:true,spelling:true,colourTarget:'unspecified',references:{venue:'The Garden Room',date:'2026-09-26'}}:getSettings();if(file.size>20*1024*1024)throw new Error('This file is larger than 20 MB. Export a smaller PDF and try again.');if(!file.name.toLowerCase().endsWith('.pdf'))throw new Error('Please choose a PDF file. Export your design as a PDF first.');}catch(e){notify(e.message);return;}
 report=null;confirmations.clear();reviewed.clear();notes='';filter='all';category='all';pageIndex=0;selectedFinding=null;$('#results').hidden=true;setBusy(true);$('#progress').value=0;$('#progress-label').textContent='Opening PDF…';controller=new AbortController();const ownController=controller;
 try{const data=bytes||new Uint8Array(await file.arrayBuffer());if(!new TextDecoder().decode(data.slice(0,1024)).includes('%PDF-'))throw new Error('This does not appear to be a PDF. Export a fresh PDF from your design app.');currentFile=file;currentBytes=data;const result=await analyzePdf(data,settings,(progress,label)=>{$('#progress').value=progress;$('#progress-label').textContent=label;},ownController.signal);if(ownController.signal.aborted)return;report={...result,name:file.name,bytes:file.size,demo:file.demo||null};renderResults();$('#step-1').classList.remove('active');$('#step-2').classList.add('active');$('#results').hidden=false;$('#results').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){report=null;notify(ownController.signal.aborted?'Check cancelled. Your file has been cleared.':error.message||'This PDF could not be checked. Try a fresh export.');currentBytes=null;currentFile=null;}finally{setBusy(false);controller=null;$('#file-input').value='';}}
$('#file-input').onchange=e=>{const file=e.target.files[0];if(file)startCheck(file);};
$('#cancel-button').onclick=()=>{controller?.abort();$('#progress-label').textContent='Cancelling…';};
const zone=$('#dropzone');['dragenter','dragover'].forEach(name=>zone.addEventListener(name,e=>{e.preventDefault();zone.classList.add('dragging');}));['dragleave','drop'].forEach(name=>zone.addEventListener(name,e=>{e.preventDefault();zone.classList.remove('dragging');}));zone.addEventListener('drop',e=>{if(e.dataTransfer.files.length!==1)return notify('Choose one PDF at a time.');startCheck(e.dataTransfer.files[0]);});
$('#sample-button').onclick=()=>{
 if(busy)return;
 $('#dialog-content').innerHTML=`<div class="demo-heading"><span class="eyebrow">SPOT THE MISTAKE</span><h2>Would you send this to print?</h2><p>Take a closer look at this sample invitation. Then reveal what the checker finds.</p></div><div class="demo-layout"><img src="./samples/invitation-preview.jpg" alt="Sample invitation: Friday, 26 September 2026, 6 PM at The Garden Room. A QR code and a small line along the bottom edge are included."><div class="demo-prompt"><h3>What's your first impression?</h3><button class="primary-button" id="demo-ready">Looks ready to print</button><button class="secondary-button" id="demo-unsure">Something looks off</button><p class="small-note">A fictional example. No upload needed.</p></div></div>`;
 dialog.classList.add('demo-dialog');dialog.showModal();dialog.addEventListener('close',()=>dialog.classList.remove('demo-dialog'),{once:true});
 const reveal=async guess=>{dialog.close();try{const r=await fetch('./samples/invitation-with-mistakes.pdf');if(!r.ok)throw new Error('The sample could not be loaded. Please try again.');const data=new Uint8Array(await r.arrayBuffer());await startCheck({name:'Sample invitation — deliberate mistakes.pdf',size:data.length,demo:guess},data);}catch(e){notify(e.message);}};
 $('#demo-ready').onclick=()=>reveal('ready');$('#demo-unsure').onclick=()=>reveal('unsure');
};
function reset(){if(busy)return;report=null;currentBytes=null;currentFile=null;confirmations.clear();reviewed.clear();notes='';$('#results').hidden=true;$('#results').innerHTML='';$('#setup').hidden=false;$('#step-1').classList.add('active');$('#step-2').classList.remove('active');$('#step-3').classList.remove('active');notify('');$('#setup').scrollIntoView({behavior:'smooth'});}
function renderResults(){const warnings=report.findings.filter(f=>f.severity==='warning').length,manual=report.findings.filter(f=>f.severity==='manual').length,passes=report.findings.filter(f=>f.severity==='pass').length;
 $('#results').innerHTML=`${report.demo?`<div class="demo-reveal"><span class="eyebrow">THE REVEAL</span><h3>${warnings} things worth a second look.</h3><p>${report.demo==='ready'?'A design can look finished and still have print issues.':'Here is what the automated check picked up.'} Explore the numbered markers. Some checks, like declared bleed, apply to the whole page.</p><small>Sample checked with 300 DPI, a 3 mm margin, bleed, English OCR and spelling enabled. Reference: The Garden Room, 26 September 2026. Your own settings are unchanged.</small></div>`:''}<div class="result-top"><div><div class="eyebrow">YOUR SECOND LOOK</div><h2>${warnings?'A few things to look at.':'Automated checks complete.'}</h2><p class="file-meta">${esc(report.name)} <span>· ${report.pages.length} page${report.pages.length===1?'':'s'} · ${report.bytes<1024*1024?(report.bytes/1024).toFixed(1)+' KB':(report.bytes/1024/1024).toFixed(1)+' MB'}</span></p></div><div class="result-actions"><button class="secondary-button" id="new-file">Check another PDF</button><button class="primary-button" id="download-report">Download report <span aria-hidden="true">↓</span></button></div></div>
 <div class="summary-grid"><div class="summary-card attention"><span>${warnings}</span><div><strong>Needs attention</strong><small>Review before printing</small></div></div><div class="summary-card manual"><span>${manual}</span><div><strong>Human checks</strong><small>Details to confirm</small></div></div><div class="summary-card passed"><span>${passes}</span><div><strong>Automated checks passed</strong><small>Within the selected settings</small></div></div></div>
 <div class="report-settings">${report.settings.dpi} DPI target <span>·</span> ${report.settings.margin} mm text margin <span>·</span> ${report.settings.bleed?'3 mm declared bleed check':'Bleed check off'} <span>·</span> English OCR ${report.settings.ocr?'on':'off'} <span>·</span> Spelling ${report.settings.spelling?'on':'off'} <button id="change-settings" class="text-button">Change & recheck</button></div>
 <div class="review-workspace"><aside class="preview-panel"><div class="preview-toolbar"><strong>Page preview</strong><div><button id="prev-page" aria-label="Previous page">‹</button><span id="page-counter"></span><button id="next-page" aria-label="Next page">›</button></div></div><div class="artboard" id="artboard"></div><div class="preview-caption" id="preview-caption"></div><p class="preview-help">Tap a numbered marker to see the issue and suggested fix. Highlighted bounds are estimates.</p><details class="extracted"><summary>Read the extracted text</summary><strong class="text-source-label">Selectable PDF text</strong><pre id="extracted-text"></pre><strong class="text-source-label">English OCR · verify the reading</strong><pre id="ocr-text"></pre></details></aside>
 <div class="findings-panel"><div class="findings-heading"><h3>What we found</h3><label class="sr-only" for="category-filter">Filter by check</label><select id="category-filter"><option value="all">All checks</option>${Object.entries(labels).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></div><div class="filter-tabs" role="group" aria-label="Filter findings"><button data-filter="all" aria-pressed="true">All findings</button><button data-filter="warning" aria-pressed="false">Attention</button><button data-filter="manual" aria-pressed="false">Human checks</button><button data-filter="pass" aria-pressed="false">Passed</button></div><div id="findings-list"></div></div></div>
 <section class="destinations" id="destinations"></section>
 <section class="final-section" id="final-checklist"><div class="final-intro"><div class="eyebrow">OPTIONAL FINAL CONFIRMATIONS</div><h2>Confirm your intended details.</h2><p>Your report is ready to export. Optionally record checks of your intended wording and production requirements.</p><span class="checklist-progress" id="checklist-progress"></span><p class="small-note">Confirmations record your review. They do not clear automated findings or certify the file.</p></div><div class="checklist-items">${checklistFor(report.settings.type).map(([id,title,detail])=>`<label class="review-check"><input type="checkbox" data-confirm="${id}"><span><strong>${title}</strong><small>${detail}</small></span></label>`).join('')}<label for="review-notes" class="notes-label">Notes for your designer or printer</label><textarea id="review-notes" maxlength="3000" placeholder="For example: please correct the weekday and re-export with 3 mm bleed." rows="3"></textarea></div></section>
 <div class="report-bottom"><p><strong>Keep the findings with your file.</strong><br>Your report includes every finding, your confirmations and notes.</p><button class="primary-button" id="download-report-bottom">Download report <span aria-hidden="true">↓</span></button></div><p class="report-disclaimer">Not a full production preflight. Font data and colour-space checks are structural. Font integrity, colour accuracy, ink limits, overprint and a physical proof still need your printer’s review. No professional reviewer has checked this file.</p>`;
 $('#new-file').onclick=reset;$('#download-report').onclick=downloadReport;$('#download-report-bottom').onclick=downloadReport;
 $('#change-settings').onclick=()=>{report=null;$('#results').hidden=true;$('#setup').hidden=false;$('#step-2').classList.remove('active');$('#step-1').classList.add('active');$('#step-3').classList.remove('active');$('#print-settings').open=true;notify('Adjust the settings, then select your PDF again to run a fresh check.');currentBytes=null;currentFile=null;$('#setup').scrollIntoView({behavior:'smooth'});};
 $('#prev-page').onclick=()=>{if(pageIndex>0){pageIndex--;selectedFinding=null;renderPage();}};$('#next-page').onclick=()=>{if(pageIndex<report.pages.length-1){pageIndex++;selectedFinding=null;renderPage();}};
 document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{filter=button.dataset.filter;renderFindings();});$('#category-filter').onchange=e=>{category=e.target.value;renderFindings();};
 document.querySelectorAll('[data-confirm]').forEach(input=>input.onchange=()=>{input.checked?confirmations.add(input.dataset.confirm):confirmations.delete(input.dataset.confirm);updateChecklist();});$('#review-notes').oninput=e=>notes=e.target.value;
 renderPage();renderFindings();renderDestinations();updateChecklist();}
function warningNumber(f){return report.findings.filter(v=>v.severity==='warning').findIndex(v=>v.id===f.id)+1;}
function previewBounds(page,rect){const m=page.viewTransform;const pts=[[rect[0],rect[1]],[rect[2],rect[1]],[rect[2],rect[3]],[rect[0],rect[3]]].map(([x,y])=>[m[0]*x+m[2]*y+m[4],m[1]*x+m[3]*y+m[5]]);const xs=pts.map(p=>p[0]/page.previewWidth*100),ys=pts.map(p=>p[1]/page.previewHeight*100);const left=Math.max(0,Math.min(100,Math.min(...xs))),top=Math.max(0,Math.min(100,Math.min(...ys)));return {left,top,width:Math.max(1,Math.min(100,Math.max(...xs))-left),height:Math.max(1,Math.min(100,Math.max(...ys))-top)};}
function selectFinding(id){const f=report.findings.find(v=>v.id===id);if(!f)return;selectedFinding=id;if(f.page)pageIndex=f.page-1;renderPage();renderFindings();}
function renderPage(){
 const page=report.pages[pageIndex];$('#page-counter').textContent=`${pageIndex+1} / ${report.pages.length}`;$('#prev-page').disabled=pageIndex===0;$('#next-page').disabled=pageIndex===report.pages.length-1;
 const warnings=report.findings.filter(f=>f.page===page.number&&f.severity==='warning');const selected=report.findings.find(f=>f.id===selectedFinding);let overlays='';
 for(const f of warnings.filter(f=>f.rect)){const r=previewBounds(page,f.rect);if(selectedFinding===f.id)overlays+=`<span class="finding-highlight" style="left:${r.left}%;top:${r.top}%;width:${r.width}%;height:${r.height}%"></span>`;overlays+=`<button class="issue-pin ${selectedFinding===f.id?'is-selected':''}" data-pin="${f.id}" aria-label="Issue ${warningNumber(f)}: ${esc(f.title)}" aria-pressed="${selectedFinding===f.id}" style="left:${Math.max(6,Math.min(94,r.left+r.width))}%;top:${Math.max(5,Math.min(95,r.top))}%">${warningNumber(f)}</button>`;}
 if(selected?.rect&&selected.page===page.number&&selected.severity!=='warning'){const r=previewBounds(page,selected.rect);overlays+=`<span class="finding-highlight" style="left:${r.left}%;top:${r.top}%;width:${r.width}%;height:${r.height}%"></span>`;}
 $('#artboard').innerHTML=`<div class="page-sheet"><img src="${page.preview}" alt="Preview of PDF page ${page.number}">${overlays}</div>`;
 let tools=$('#page-annotations');if(!tools){tools=document.createElement('div');tools.id='page-annotations';$('#artboard').after(tools);}
 tools.innerHTML=`${warnings.some(f=>!f.rect)?`<div class="pagewide-issues"><span>Whole-page checks</span>${warnings.filter(f=>!f.rect).map(f=>`<button data-pin="${f.id}" class="pagewide-button" aria-pressed="${selectedFinding===f.id}"><b>${warningNumber(f)}</b> ${esc(labels[f.category])}</button>`).join('')}</div>`:''}${selected&&selected.page===page.number?`<div class="annotation-detail" aria-live="polite"><strong>${selected.severity==='warning'?`Issue ${warningNumber(selected)} · `:''}${esc(selected.title)}</strong><p>${esc(selected.detail)}</p></div>`:''}`;
 document.querySelectorAll('[data-pin]').forEach(button=>button.onclick=()=>{const id=button.dataset.pin;selectFinding(id);document.querySelector(`[data-pin="${id}"]`)?.focus({preventScroll:true});});
 $('#preview-caption').textContent=`${page.width.toFixed(1)} × ${page.height.toFixed(1)} mm · PDF trim size`;$('#extracted-text').textContent=page.text||'No selectable text found.';$('#ocr-text').textContent=page.ocrText||'No OCR text available. Check the text-recognition findings.';
}
function renderFindings(){document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));const findings=report.findings.filter(f=>(filter==='all'||f.severity===filter)&&(category==='all'||f.category===category)).sort((a,b)=>({warning:0,manual:1,info:2,pass:3}[a.severity]-{warning:0,manual:1,info:2,pass:3}[b.severity]));$('#findings-list').innerHTML=findings.length?findings.map(f=>`<article class="finding ${f.severity} ${selectedFinding===f.id?'selected':''}"><div class="finding-icon" aria-hidden="true">${f.severity==='warning'?warningNumber(f):{manual:'?',pass:'✓',info:'i'}[f.severity]}</div><div class="finding-body"><div class="finding-meta"><span>${labels[f.category]}${f.page?' · Page '+f.page:''}</span><span class="status-label">${statusLabels[f.severity]}</span></div><button class="finding-title" data-finding="${f.id}">${esc(f.title)}</button><p>${esc(f.detail)}</p>${f.severity==='warning'?`<label class="ack-label"><input type="checkbox" data-reviewed="${f.id}" ${reviewed.has(f.id)?'checked':''}> Noted for correction or printer review</label>`:''}</div></article>`).join(''):'<div class="empty-results">No findings in this filter. Other checks may still need review.</div>';
 document.querySelectorAll('[data-finding]').forEach(button=>button.onclick=()=>{const f=report.findings.find(v=>v.id===button.dataset.finding);selectedFinding=f.id;if(f.page)pageIndex=f.page-1;renderPage();renderFindings();if(matchMedia('(max-width:800px)').matches)$('#artboard').scrollIntoView({behavior:'smooth',block:'center'});});document.querySelectorAll('[data-reviewed]').forEach(input=>input.onchange=()=>{input.checked?reviewed.add(input.dataset.reviewed):reviewed.delete(input.dataset.reviewed);});}
function renderDestinations(){const items=report.pages.flatMap(p=>[...p.codes.map(c=>({...c,kind:'QR code',page:p.number})),...p.links.map(c=>({...c,kind:'PDF link',page:p.number}))]);$('#destinations').innerHTML=`<div class="panel-heading"><h3>Check the destinations</h3><span>NO LINKS VISITED AUTOMATICALLY</span></div>${items.length?items.map(item=>`<div class="destination"><span class="destination-type">${item.kind} · Page ${item.page}</span><code>${esc(item.data.slice(0,2000))}</code>${item.url?`<a class="secondary-button" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">Open destination ↗</a>`:'<span class="non-link">Text or unsupported link type</span>'}</div>`).join(''):'<p>No QR destinations or web link annotations were found. If your artwork includes a code, scan it yourself; detection can miss small or stylised codes.</p>'}<p class="small-note">Opening a link does not confirm it is correct. Check the destination’s content and test a printed proof.</p>`;}
function updateChecklist(){const total=checklistFor(report.settings.type).length;$('#checklist-progress').textContent=`${confirmations.size} of ${total} confirmed`;$('#step-3').classList.toggle('active',confirmations.size===total);}
function downloadReport(){if(!report)return;const warnings=report.findings.filter(f=>f.severity==='warning').length;const findings=report.findings.map(f=>`<tr><td>${esc(statusLabels[f.severity])}</td><td>${f.page||'All'}</td><td><strong>${esc(f.title)}</strong><br>${esc(f.detail)}${reviewed.has(f.id)?'<br><em>User noted this for correction or printer review.</em>':''}</td></tr>`).join('');const checklist=checklistFor(report.settings.type).map(([id,title])=>`<li>${confirmations.has(id)?'CONFIRMED':'NOT CONFIRMED'} — ${esc(title)}</li>`).join('');const urls=report.pages.flatMap(p=>[...p.codes,...p.links].map(c=>`<li>Page ${p.number}: ${esc(c.data)} — destination not verified by this tool.</li>`)).join('');
 const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Print review — ${esc(report.name)}</title><style>body{font:15px/1.6 Arial,sans-serif;color:#192334;max-width:950px;margin:40px auto;padding:0 24px}h1{font:38px Georgia,serif}h2{margin-top:32px;font-size:21px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccd3df;padding:12px;text-align:left;vertical-align:top}td:first-child{width:120px}p,li,td{overflow-wrap:anywhere}small{color:#526070}.banner{background:#eef1ff;padding:18px;border-left:4px solid #3452dc}button{padding:12px 18px;background:#3452dc;color:white;border:0;border-radius:6px;cursor:pointer}.notes{white-space:pre-wrap}@media print{button{display:none}body{margin:0}tr{break-inside:avoid}thead{display:table-header-group}}</style></head><body><small>BEFORE YOU PRINT / REVIEW REPORT</small><h1>${esc(report.name)}</h1><p>Checked ${esc(new Date(report.checkedAt).toLocaleString())} · ${report.pages.length} page(s)</p><div class="banner"><strong>${warnings} automated finding(s) need attention. ${confirmations.size}/${checklistFor(report.settings.type).length} manual items confirmed.</strong><br>This is a self-review report, not print approval or professional certification.</div><p>Settings: ${report.settings.dpi} DPI target; ${report.settings.margin} mm text margin; ${report.settings.bleed?'3 mm declared bleed check':'bleed check skipped'}; ${report.settings.size?esc(report.settings.size.join(' × '))+' mm target':'PDF trim size used'}. Measurements use the original PDF size. English OCR: ${report.settings.ocr?'on':'off'}; British English spelling: ${report.settings.spelling?'on':'off'}; colour requirement: ${report.settings.colourTarget==='cmyk'?'CMYK requested':'not specified'}.</p><button onclick="window.print()">Print / save as PDF</button><h2>Findings</h2><table><thead><tr><th>Status</th><th>Page</th><th>Finding and next step</th></tr></thead><tbody>${findings}</tbody></table><h2>Your final checklist</h2><ul>${checklist}</ul><h2>Your notes</h2><p class="notes">${esc(notes||'No notes added.')}</p><h2>Decoded QR contents and PDF links</h2><ul>${urls||'<li>No destinations detected. This does not establish that none are present.</li>'}</ul><h2>Scope and limits</h2><p>This tool checks page boxes, measurable raster-image resolution, estimated selectable-text margins, a limited set of English date patterns, QR decodability, referenced font embedding and source colour spaces. English OCR and dictionary suggestions are fallible. Supplied reference details are compared for presence, not factual truth or placement. Font checks inspect embedded data presence; colour checks identify source spaces and output-profile presence. It does not verify grammar, intended meaning, link availability, font integrity, colour accuracy, ink coverage, overprint, PDF/X compliance or physical print quality. Complex PDF content may produce false positives or be missed. No professional reviewer has checked this file. Confirm all production requirements with your printer and request a physical proof.</p><small>Generated locally. Your source PDF was not uploaded.</small></body></html>`;
 const blob=new Blob([html],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const filename='print-review-'+report.name.replace(/\.pdf$/i,'').replace(/[^a-z0-9_-]/gi,'-').slice(0,70)+'.html';
 $('#dialog-content').innerHTML='<h2>Your review report.</h2><p>Save a report file to share, or use your browser’s print dialog to save a PDF. The report includes every finding, even when you filter the on-screen list.</p><div class="export-actions"><a class="primary-button" id="save-report">Save report file ↓</a><button class="secondary-button" id="print-report">Print / save as PDF</button></div><iframe id="report-frame" title="Printable review report"></iframe><p class="small-note">If downloads are unavailable in this preview, use Print / save as PDF or open the website in your regular browser.</p>';
 const a=$('#save-report');a.href=url;a.download=filename;
 const frame=$('#report-frame');frame.srcdoc=html;$('#print-report').onclick=()=>frame.contentWindow.print();
 dialog.classList.add('export-dialog');dialog.showModal();dialog.addEventListener('close',()=>{URL.revokeObjectURL(url);dialog.classList.remove('export-dialog');},{once:true});}
if(document.modelContext?.registerTool){try{const life=new AbortController();document.modelContext.registerTool({name:'read_print_findings',description:'Read the current PDF check findings and manual confirmation count. Does not open files, visit links or approve artwork.',inputSchema:{type:'object',properties:{severity:{type:'string',enum:['all','warning','manual','pass','info']}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='severity')||input.severity&&!['all','warning','manual','pass','info'].includes(input.severity))throw new Error('Invalid severity filter.');if(!report)return {status:'no_file',message:'Choose a PDF or try the sample first.'};return {name:report.name,pages:report.pages.length,confirmed:confirmations.size,findings:report.findings.filter(f=>!input.severity||input.severity==='all'||input.severity===f.severity).map(({rect,...f})=>f)};}},{signal:life.signal});addEventListener('pagehide',()=>life.abort(),{once:true});}catch{}}
